/*
 * BGP YANG Notifications (bgp_nb_notifications.c)
 * Note: Use int for FSM state to avoid forward declaration issues.
 * Callers should pass enum bgp_fsm_status values.
 */

/* Peer state change notification - sent on any FSM state transition */
void bgp_notif_state_change(const struct peer *peer, int old_state,
			    int new_state);

/* Peer established notification - sent when peer reaches Established state */
void bgp_notif_peer_established(const struct peer *peer);

/* Backward transition notification - sent when peer leaves Established state */
void bgp_notif_backward_transition(const struct peer *peer, int old_state,
				   int new_state, const char *reason,
				   uint8_t error_code, uint8_t error_subcode);

/* NOTIFICATION received from peer */
void bgp_notif_notification_received(const struct peer *peer, uint8_t error_code,
				     uint8_t error_subcode, const uint8_t *data_buf,
				     size_t data_len);

/* NOTIFICATION sent to peer */
void bgp_notif_notification_sent(const struct peer *peer, uint8_t error_code,
				 uint8_t error_subcode, const uint8_t *data_buf,
				 size_t data_len);

/* Prefix limit reached notification */
void bgp_notif_prefix_limit_reached(const struct peer *peer, afi_t afi,
				    safi_t safi, uint32_t prefix_limit,
				    uint32_t prefix_count, int action);

/* cli_show callbacks for YANG nodes */
void bgp_global_ebgp_requires_policy_cli_show(struct vty *vty, const struct lyd_node *dnode, bool show_defaults);
void bgp_global_suppress_duplicates_cli_show(struct vty *vty, const struct lyd_node *dnode, bool show_defaults);
void bgp_global_enforce_first_as_cli_show(struct vty *vty, const struct lyd_node *dnode, bool show_defaults);
void bgp_global_log_neighbor_changes_cli_show(struct vty *vty, const struct lyd_node *dnode, bool show_defaults);
void bgp_global_graceful_restart_notification_cli_show(struct vty *vty, const struct lyd_node *dnode, bool show_defaults);

